-- Layout: 16x8, 2 pages, 3 regions
--   page 1 "drums":
--     - "pages" (2 cells, page select global, 2 cells)
--     - "pads" (4 cells, momentary per_cell, ch1 note from MIDI 36)
--   page 2 "keys":
--     - "keys" (8 cells, momentary per_cell, ch1 note from MIDI 60)
